typedef struct yyjson_alc {
    void *(*malloc)(void *ctx, size_t size);
    void *(*realloc)(void *ctx, void *ptr, size_t old_size, size_t size);
    void (*free)(void *ctx, void *ptr);
    void *ctx;
} yyjson_alc;

typedef struct yyjson_read_err {
    yyjson_read_code code;
    const char *msg;
    size_t pos;
} yyjson_read_err;

typedef struct yyjson_write_err {
    yyjson_write_code code;
    const char *msg;
} yyjson_write_err;

typedef struct yyjson_arr_iter {
    size_t idx;
    size_t max;
    yyjson_val *cur;
} yyjson_arr_iter;

typedef struct yyjson_obj_iter {
    size_t idx;
    size_t max;
    yyjson_val *cur;
    yyjson_val *obj;
} yyjson_obj_iter;

typedef struct yyjson_mut_arr_iter {
    size_t idx;
    size_t max;
    yyjson_mut_val *cur;
    yyjson_mut_val *pre;
    yyjson_mut_val *arr;
} yyjson_mut_arr_iter;

typedef struct yyjson_mut_obj_iter {
    size_t idx;
    size_t max;
    yyjson_mut_val *cur;
    yyjson_mut_val *pre;
    yyjson_mut_val *obj;
} yyjson_mut_obj_iter;

typedef struct yyjson_ptr_err {
    yyjson_ptr_code code;
    const char *msg;
    size_t pos;
} yyjson_ptr_err;

typedef struct yyjson_ptr_ctx {
    yyjson_mut_val *ctn;
    yyjson_mut_val *pre;
    yyjson_mut_val *old;
} yyjson_ptr_ctx;

typedef struct yyjson_patch_err {
    yyjson_patch_code code;
    size_t idx;
    const char *msg;
    yyjson_ptr_err ptr;
} yyjson_patch_err;

typedef union yyjson_val_uni {
    uint64_t    u64;
    int64_t     i64;
    double      f64;
    const char *str;
    void       *ptr;
    size_t      ofs;
} yyjson_val_uni;

struct yyjson_val {
    uint64_t tag;
    yyjson_val_uni uni;
};

struct yyjson_doc {
    yyjson_val *root;
    yyjson_alc alc;
    size_t dat_read;
    size_t val_read;
    char *str_pool;
};

struct yyjson_mut_val {
    uint64_t tag;
    yyjson_val_uni uni;
    yyjson_mut_val *next;
};

typedef struct yyjson_str_chunk {
    struct yyjson_str_chunk *next;
    size_t chunk_size;
} yyjson_str_chunk;

typedef struct yyjson_str_pool {
    char *cur;
    char *end;
    size_t chunk_size;
    size_t chunk_size_max;
    yyjson_str_chunk *chunks;
} yyjson_str_pool;

typedef struct yyjson_val_chunk {
    struct yyjson_val_chunk *next;
    size_t chunk_size;
} yyjson_val_chunk;

typedef struct yyjson_val_pool {
    yyjson_mut_val *cur;
    yyjson_mut_val *end;
    size_t chunk_size;
    size_t chunk_size_max;
    yyjson_val_chunk *chunks;
} yyjson_val_pool;

struct yyjson_mut_doc {
    yyjson_mut_val *root;
    yyjson_alc alc;
    yyjson_str_pool str_pool;
    yyjson_val_pool val_pool;
};

