// No inputs, returns a version number; just call to exercise API.
uint32_t v = yyjson_version();
// Property: major should be non-zero for released builds; can't assert universally here.
(void)v;
// Validation: Simple call with no side effects; nothing to output.

// Initialize a pool allocator with a persistent heap buffer.
// Requirements: alc != NULL, buf != NULL, size >= 8 words (assume 64-bit => >=64 bytes).
size_t min_words = 8u;
size_t word_size = sizeof(void*);
size_t min_bytes = min_words * word_size;
size_t extra = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u);
size_t buf_size = min_bytes + (extra & ~((size_t)0));
if (buf_size < min_bytes) buf_size = min_bytes; // enforce
char *heap_buf = (char*)malloc(buf_size);
if (!heap_buf) { FUZZ_BAIL(); }
// Call the API
bool ok = yyjson_alc_pool_init(alc, (void*)heap_buf, buf_size);
if (!ok) { FUZZ_BAIL(); }
// Track allocator kind and buffer so later stubs can respect lifetime and semantics.
FUZZ_SET_ATTR_STR(alc, "alc_kind", "pool");
FUZZ_SET_ATTR_PTR(alc, "pool_buf", heap_buf);
FUZZ_SET_ATTR_INT(alc, "pool_size", (int)buf_size);
// Outputs: return initialized alc and the buffer to keep it alive across calls
void *pool_buf = (void*)heap_buf;
(void)pool_buf;
// Validation: Ensures non-NULL alc/buffer and size >= 8 words; stores attributes for correct downstream use.

// Create a dynamic allocator; returns NULL on failure.
yyjson_alc *alc = yyjson_alc_dyn_new();
if (!alc) { FUZZ_BAIL(); }
// Mark as dynamic so free stub can validate correct usage.
FUZZ_SET_ATTR_STR(alc, "alc_kind", "dyn");
// Validation: Allocator created and tagged; returned for later use.

// Free a dynamic allocator. Safe with NULL, but we enforce correct type when non-NULL.
const char *kind = FUZZ_GET_ATTR_STR(alc, "alc_kind");
int is_dyn = kind && kind[0] && (strcmp(kind, "dyn") == 0);
if (!is_dyn) { FUZZ_BAIL(); }
// Invoke free
yyjson_alc_dyn_free(alc);
// Validation: Ensures only dynamic allocators created by yyjson_alc_dyn_new are freed here.

// Generate a random UTF-8 buffer and a valid position within [0, len].
std::string s = FUZZ_PARAM_STR();
size_t len = s.size();
size_t pos = (len == 0) ? 0u : ((size_t)*FUZZ_PARAM(unsigned int) % (len + 1u));
size_t line = 0, col = 0, chr = 0;
bool want_line = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
bool want_col  = ((*FUZZ_PARAM(unsigned int)) & 2u) != 0u;
bool want_chr  = ((*FUZZ_PARAM(unsigned int)) & 4u) != 0u;
size_t *pline = want_line ? &line : nullptr;
size_t *pcol  = want_col  ? &col  : nullptr;
size_t *pchr  = want_chr  ? &chr  : nullptr;
// Call API (str must not be NULL)
bool ok = yyjson_locate_pos(s.c_str(), len, pos, pline, pcol, pchr);
(void)ok; (void)line; (void)col; (void)chr;
// Validation: Ensures pos within [0,len] and optional outputs may be NULL.

// Parse JSON from a mutable buffer. Requirements: dat!=NULL, len>0. Avoid INSITU flag complexity by using flg=0.
std::string s = FUZZ_PARAM_STR();
if (s.size() == 0) { FUZZ_BAIL(); }
// Make buffer mutable
s.push_back('\0');
char *dat = &s[0];
size_t len = s.size() - 1; // exclude the added terminator
const yyjson_alc *alc = nullptr; // use default allocator
yyjson_read_err err = {};
yyjson_read_flag flg = 0u;
yyjson_doc *doc = yyjson_read_opts(dat, len, flg, alc, &err);
if (!doc) { FUZZ_BAIL(); }
// Validation: Provides non-empty buffer, flg=0 (no in-situ), checks for successful parse and returns doc.

// Read from a fuzz-generated file path. Requirements: path!=NULL.
