yyjson_read_err err = {};
yyjson_read_flag flg = 0u;
yyjson_doc *doc = yyjson_read_file(path, flg, alc, &err);
if (!doc) { FUZZ_BAIL(); }
// Validation: Uses valid path with random contents; bails unless parse succeeds and returns a doc.

