yyjson_read_flag flg = (yyjson_read_flag)0u; // keep simple
size_t max_mem = yyjson_read_max_memory_usage(len, flg);
(void)max_mem;
// Validation: Simple pure computation with bounded len; no side effects.

// Parse a single JSON number from a null-terminated string into an immutable value struct.
std::string s = FUZZ_PARAM_STR();
// Ensure it is null-terminated and non-empty to exercise parser
if (s.empty()) s = "0";
const char *dat = s.c_str();
yyjson_val val = {};
yyjson_read_err err = {};
yyjson_read_flag flg = (yyjson_read_flag)(*FUZZ_PARAM(unsigned int) & 0u); // restrict to supported flags subset (0)
const char *end = yyjson_read_number(dat, &val, flg, nullptr, &err);
(void)end; (void)val;
// Validation: Supplies required non-NULL dat/val; does not persist any resources.

// Parse a single JSON number into a mutable value struct.
