const char *dat = s.c_str();
yyjson_mut_val val = {};
yyjson_read_err err = {};
yyjson_read_flag flg = (yyjson_read_flag)0u;
const char *end = yyjson_mut_read_number(dat, &val, flg, nullptr, &err);
(void)end; (void)val;
// Validation: Meets non-NULL requirements; no persistent allocations.

// Serialize immutable document to a newly allocated string. Requirements: doc!=NULL and has root.
yyjson_val *root = yyjson_doc_get_root(doc);
if (!root) { FUZZ_BAIL(); }
yyjson_write_err err = {};
size_t out_len = 0;
const yyjson_alc *alc = nullptr;
yyjson_write_flag flg = (yyjson_write_flag)(*FUZZ_PARAM(unsigned int) & 0u); // use 0 for broad compatibility
char *out_cstr = yyjson_write_opts(doc, flg, alc, &out_len, &err);
if (!out_cstr) { FUZZ_BAIL(); }
void *out_str = (void*)out_cstr;
(void)out_str; (void)out_len;
// Validation: Ensures doc has root; captures allocated buffer as opaque output for later freeing.

// Write immutable document to a fuzz-provided file.
