if (!root) { FUZZ_BAIL(); }
const char *path = FUZZ_PARAM_FILENAME();
yyjson_write_err err = {};
const yyjson_alc *alc = nullptr;
yyjson_write_flag flg = (yyjson_write_flag)0u;
bool ok = yyjson_write_file(path, doc, flg, alc, &err);
(void)ok;
// Validation: Enforces non-NULL root; no persistent outputs.

